# (feastDate, English name, Turkish name, Turkish description, Turkish patronOf) - Protestant / Anglican calendars, July to December
DATA = [
    ("July 1", "Catherine Winkworth and John Mason Neale", "Catherine Winkworth ve John Mason Neale", "On dokuzuncu yüzyılın ilahi çevirmenleri. Catherine Winkworth (1827-1878), 'Now Thank We All Our God' gibi Alman koralleri İngilizceye çevirdi; John Mason Neale (1818-1866) 'O Come, O Come, Emmanuel' dahil Yunanca ve Latince ilahileri çevirdi.", "İlahi çevirmenleri, korolar"),
    ("July 2", "Moses the Black", "Siyah Musa", "Mısır çölünde keşiş olan ve nezaket öğreten eski bir Etiyopyalı haydut (yaklaşık 330-405). Savaşmayı reddederken akıncılar tarafından öldürüldü.", "Dönüşen suçlular, şiddetsizlik"),
    ("July 3", "Thomas, Apostle", "Havari Tomas", "Dirilmiş Rab'bi görene dek şüphe eden, sonra 'Rabbim ve Tanrım' diye itiraf eden havari. Gelenek, İncil'i Hindistan'a taşıdığını söyler.", "Hindistan, şüphe edenler"),
    ("July 4", "Independence Day", "Bağımsızlık Günü", "Episkopal Kilisesi, Amerikan Bağımsızlık Bildirgesi'nin yıldönümünü ulus ve halkı için duayla anar.", "Ulus, ülkesi için dua edenler"),
    ("July 5", "Cyril and Methodius", "Cyril ve Methodius", "Slovak Lutheran kiliseler, dokuzuncu yüzyılda Slavlara İncil'i getiren ve onlara yazılı bir dil veren kardeşleri anar.", "Slavlar, çevirmenler"),
    ("July 6", "Jan Hus", "Jan Hus", "Halkın dilinde Kutsal Kitap'tan vaaz veren ve 6 Temmuz'da Konstanz'da kazığa bağlanıp yakılan Çek rahip ve reformcu (yaklaşık 1372-1415). Moravya ve diğer Protestan kiliseler köklerini onun tanıklığına dayandırır.", "Çek toprakları, hakikat için ayakta duranlar"),
    ("July 8", "Priscilla and Aquila", "Priscilla ve Aquila", "Episkopal Kilisesi, Pavlus'u ağırlayan ve Apollos'a öğreten, evlilikte ortak hizmetin örneği çifti anar.", "Evli çiftler"),
    ("July 10", "John Calvin's Birthday", "John Calvin'in Doğum Günü", "John Calvin 10 Temmuz 1509'da Fransa'nın Noyon kentinde doğdu. Cenevre reformcusu; 'Hıristiyan Dininin Esasları' dünya çapında Reformed kiliseleri şekillendirdi.", "Reformed kiliseler, ilahiyatçılar"),
    ("July 11", "Benedict of Nursia", "Nursia'lı Benedictus", "Kuralı dua ve çalışma dengesiyle Batı manastırcılığını şekillendiren İtalyan başrahip (yaklaşık 480-547). Lutheranlar ve Anglikanlar onu 11 Temmuz'da anar.", "Keşişler, öğrenciler, Avrupa"),
    ("July 12", "Nathan Soderblom", "Nathan Söderblom", "Erken ekümenik hareketin önderi, 1925'te 'Yaşam ve Çalışma' Stockholm konferansını toplayan ve 1930'da Nobel Barış Ödülü'nü kazanan Uppsala Başpiskoposu (1866-1931).", "Kilise birliği, barış yapıcılar"),
    ("July 14", "Argula von Grumbach", "Argula von Grumbach", "Lutheran görüşleri nedeniyle zulüm gören bir öğrenciyi savunmak için Ingolstadt Üniversitesi'ne yazan ve Reform'un ilk kadın yazarlarından biri olan Bavyeralı soylu kadın (yaklaşık 1492-1554).", "Kadın yazarlar, vicdan için konuşanlar"),
    ("July 15", "The Division of the Holy Apostles", "Kutsal Havariler'in Dağılışı", "Havarilerin İncil'i yeryüzünün uçlarına taşımak için Kudüs'ten ayrılışını hatırlayan tarihsel bayram.", "Misyonerler"),
    ("July 16", "Ruth the Moabite", "Moablı Rut", "Naomi'ye 'nereye gidersen ben de oraya gideceğim' diyen, İsrail'e katılan ve Kral Davut'un büyük büyükannesi ve İsa'nın atası olan kadın.", "Gelinler, sadık dostlar, göçmenler"),
    ("July 17", "Isaac Watts' Birthday and William White", "Isaac Watts'ın Doğum Günü ve William White", "'İngiliz ilahi yazımının babası' Isaac Watts 17 Temmuz 1674'te doğdu. William White (1748-1836) Pennsylvania'nın ilk Episkopal piskoposuydu ve erken Episkopal Kilisesi'ni şekillendirdi.", "İlahi yazarları, piskoposlar"),
    ("July 19", "Macrina the Younger", "Genç Macrina", "Basil ve Nyssalı Gregory'nin kız kardeşi (yaklaşık 327-379); aile evini bir dua topluluğuna dönüştürdü ve kardeşlerine öğretti.", "Öğretmenler, imandaki kız kardeşler"),
    ("July 20", "Elijah the Prophet", "Peygamber İlyas", "Karmel Dağı'nda Baal peygamberleriyle yüzleşen ve Rab'bi 'ince bir fısıltı' sesinde işiten peygamber. Kasırgayla göğe alındı ve Başkalaşım'da Mesih'le göründü.", "Peygamberler, sıkıntıda dua edenler"),
    ("July 21", "Ezekiel the Prophet", "Peygamber Hezekiel", "Babil'de sürgündeki rahip ve peygamber; Tanrı'nın yüceliği ve kuru kemikler vadisinin dirilişi vizyonlarını gördü, sürgünler için umut işareti.", "Sürgünler, yenilenme umut edenler"),
    ("July 22", "Mary Magdalene", "Magdalalı Meryem", "İsa tarafından iyileştirilen, haçta kalan ve dirilmiş Rab'bi ilk gören kadın. Kilise ona 'havarilere havari' der.", "İyileşenler, kadın müritler"),
    ("July 23", "Birgitta of Sweden", "İsveçli Birgitta", "Bridgettine tarikatını kuran, vizyonlar alan ve Papa'yı Roma'ya dönmeye çağıran İsveçli soylu kadın ve mistik (yaklaşık 1303-1373).", "İsveç, mistikler, dullar"),
    ("July 24", "John Newton's Birthday and Thomas a Kempis", "John Newton'ın Doğum Günü ve Thomas a Kempis", "Köle gemisi kaptanı iken 'Amazing Grace' ilahisinin yazarı olan John Newton 24 Temmuz 1725'te (Eski Takvim; bugünkü takvimle 4 Ağustos) doğdu. 'İsa'yı Örnek Almak'ın yazarı Thomas a Kempis (yaklaşık 1380-1471) Episkopal takviminde aynı tarihte anılır.", "Günahtan kurtarılanlar, adanmışlık yazarları"),
    ("July 25", "James, Apostle", "Havari Yakup", "Kardeşi Yuhanna ile balıkçı teknelerinden çağrılan Zebedi oğlu Yakup. İman uğruna ölen On İkiler'in ilkiydi; yaklaşık 44'te Herodes Agrippa tarafından öldürüldü.", "Hacılar, balıkçılar"),
    ("July 26", "Anne and Joachim, Parents of the Virgin Mary", "Anna ve Joachim, Meryem'in Ebeveynleri", "Meryem'in ebeveynlerinin geleneksel adları; Anglikanlar tarafından büyükanne-büyükbabaların kutsaması işareti olarak anılır.", "Büyükanne-büyükbabalar"),
    ("July 27", "William Reed Huntington", "William Reed Huntington", "'Kilise Fikri' Chicago-Lambeth Dörtgeni'nin, Hıristiyan birliği için bir temelin şekillenmesine yardım eden Episkopal rahip (1838-1909).", "Ekümenistler, rahipler"),
    ("July 28", "Johann Sebastian Bach, Heinrich Schutz and George Frideric Handel", "Johann Sebastian Bach, Heinrich Schütz ve George Frideric Handel", "Kilise müziğinin üç devi. Bach (1685-1750) kantatlar, Çile Kantatları ve Si minör Ayin'i yazdı; Schütz (1585-1672) Alman kilise müziğinin babasıydı; Handel (1685-1759) 'Mesih'i yazdı.", "Müzisyenler, korolar, besteciler"),
    ("July 29", "William Wilberforce", "William Wilberforce", "Hayatını köle ticaretini sona erdirmeye adayan İngiliz evanjelik siyasetçi (1759-1833). Köleliğin Britanya İmparatorluğu'nda kaldırılacağı haberini 29 Temmuz'daki ölümünden üç gün önce duydu.", "Kölelik karşıtları, siyasetçiler"),
    ("July 30", "Robert Barnes", "Robert Barnes", "Cambridge'de eğitim gören, Luther'le arkadaşlık eden ve Smithfield'de Reform şehidi olarak yakılan İngiliz rahip (yaklaşık 1495-1540).", "Şehitler, itirafçılar"),
    ("July 31", "Joseph of Arimathea", "Arimatyalı Yusuf", "Pilatus'tan İsa'nın bedenini isteyen ve onu kendi yeni mezarına gömen zengin konsey üyesi. İmanını gizledikten sonraki cesaretiyle anılır.", "Ölüleri onurlandıranlar"),

    ("August 1", "Joseph of Arimathaea", "Arimatyalı Yusuf (Episkopal)", "Episkopal Kilisesi, İsa'nın gömülmesi için mezarını sunan öğrenci Yusuf'u onurlandırır.", "Cenaze görevlileri, müritler"),
    ("August 3", "Joanna, Mary and Salome", "Joanna, Meryem ve Salome", "Paskalya sabahı baharatlarla mezara gelen ve diriliş haberini ilk duyan kadınlardan üçü.", "Dirilişe tanıklık eden kadınlar"),
    ("August 7", "John Mason Neale", "John Mason Neale", "Sackville College'ın müdürü olan, 'Good King Wenceslas' sözleri ve 'All glory, laud and honour' dahil birçok kadim ilahiyi çeviren Anglikan rahip ve ilahi yazarı (1818-1866).", "İlahi yazarları, çevirmenler"),
    ("August 8", "Dominic", "Dominic", "İmanı vaaz ve çalışmayla öğretmek için Vaizler Tarikatı'nı kuran İspanyol rahip (yaklaşık 1170-1221). Lutheranlar ve Episkopallar onu 8 Ağustos'ta onurlandırır.", "Vaizler, bilginler"),
    ("August 9", "Edith Stein", "Edith Stein", "Katolikliğe geçen, Karmelit rahibe olan ve Auschwitz'de öldürülen Alman Yahudi filozof (1891-1942).", "Filozoflar, din değiştirenler, şehitler"),
    ("August 10", "Lawrence of Rome", "Romalı Lawrence", "Kilise'nin hazinesini teslim etmesi istendiğinde yoksulları getirip 'Kilise'nin hazineleri bunlardır' diyen Roma diyakozu. 258'de şehit edildi.", "Diyakozlar, yoksullar"),
    ("August 11", "Clare of Assisi", "Assisi'li Clare", "Francis'in arkadaşı olan, Fakir Clare'leri kuran ve San Damiano'da köklü yoksulluk içinde yaşayan İtalyan başrahibe (1194-1253).", "Tefekkür edenler, sadelik arayanlar"),
    ("August 12", "Florence Nightingale", "Florence Nightingale", "Askeri hastaneleri ıslah eden ve imanıyla yönlendirilerek modern hemşirelik mesleğini kuran İngiliz hemşire (1820-1910).", "Hemşireler"),
    ("August 13", "Florence Nightingale and Clara Maass", "Florence Nightingale ve Clara Maass", "Lutheranlar, Florence Nightingale'i ve sarı humma deneyine gönüllü olan ve hastalara hizmet ettikten sonra 24 Ağustos'ta ölen Amerikalı hemşire Clara Maass'ı (1876-1901) anar.", "Hemşireler, hastalara hizmet edenler"),
    ("August 14", "Maximilian Kolbe and Kaj Munk", "Maximilian Kolbe ve Kaj Munk", "Polonyalı Fransiskan Maximilian Kolbe 1941'de Auschwitz'te başka bir mahkûmun yerine canını verdi. Danimarkalı Lutheran papaz ve oyun yazarı Kaj Munk (1898-1944), vaazları nedeniyle Naziler tarafından öldürüldü.", "Vicdan şehitleri, mahkûmlar"),
    ("August 15", "Mary, Mother of Our Lord", "Rabbimizin Annesi Meryem", "Lutheranlar ve Anglikanlar, 'sözüne göre bana olsun' diyen, kadınlar arasında kutsanmış Rab'bin annesi Meryem'i onurlandırır.", "Anneler, Kilise"),
    ("August 16", "Isaac the Patriarch", "Patrik İshak", "Abraham ve Sara'nın vaat çocuğu; sunakta kurtarıldı ve Yakup ile Esav'ın babası oldu. Hayatı güvenle anılır.", "Tanrı'nın vaatlerine güvenenler"),
    ("August 17", "William Carey's Birthday and Johann Gerhard", "William Carey'nin Doğum Günü ve Johann Gerhard", "'Modern misyonların babası' William Carey 17 Ağustos 1761'de doğdu. Johann Gerhard (1582-1637), 'Kutsal Meditasyonlar' eseri yaygın okunan Lutheran ilahiyatçıydı.", "Misyonerler, ilahiyatçılar"),
    ("August 19", "Bernard of Clairvaux", "Clairvaux'lu Bernard", "'Jesus, the Very Thought of Thee' ve 'O Sacred Head, Now Wounded' yazarı Fransız Sistersiyen başrahip, vaiz ve ilahi yazarı (1090-1153). Lutheranlar onu 19 Ağustos'ta anar.", "Başrahipler, ilahi yazarları"),
    ("August 20", "William Booth", "William Booth", "Londra'nın yoksullarına ulaşmak için Kurtuluş Ordusu'nu kuran İngiliz Metodist vaiz (1829-1912). 20 Ağustos'ta öldü.", "Yoksullar, evsizlere hizmet edenler"),
    ("August 24", "Bartholomew, Apostle", "Havari Bartholomeos", "Genellikle İsa'nın 'hilesiz' dediği Nathanael ile özdeşleştirilen On İki Havari'den biri. Gelenek, Hindistan ve Ermenistan'da vaaz verdiğini söyler.", "Havariler, Ermenistan"),
    ("August 25", "Louis IX of France", "Fransa Kralı IX. Louis", "Sainte-Chapelle'i yaptıran, yoksullara bakan ve Tunus'ta haçlı seferinde ölen adil bir hükümdar olan Fransa kralı (1214-1270).", "Krallar, yoksullar"),
    ("August 26", "Simeon Bachos, the Ethiopian Eunuch", "Etiyopyalı Hadım Simeon Bachos", "Gazze yolunda Yeşaya'yı okuduktan sonra Filipus tarafından vaftiz edilen Etiyopya kraliçesinin saymanı. Gelenek, İncil'i Afrika'ya geri taşıdığını söyler.", "Afrika, arayanlar, yolcular"),
    ("August 27", "Thomas Gallaudet and Henry Winter Syle", "Thomas Gallaudet ve Henry Winter Syle", "Sağır topluluğa hizmet eden ve sağır cemaatleri için kiliseler kuran iki Episkopal rahip (Gallaudet, ö. 1902; Syle, ö. 1890).", "Sağırlar, sağırların öğretmenleri"),
    ("August 28", "Augustine of Hippo", "Hippo'lu Augustinus", "'İtiraflar' ve 'Tanrı Devleti'ni yazan Hippo Piskoposu (354-430). Lütuf öğretisi Luther ve Calvin'i ve Protestan Reformu'nu derinden şekillendirdi.", "İlahiyatçılar, Tanrı'yı arayanlar"),
    ("August 29", "The Beheading of John the Baptist", "Vaftizci Yahya'nın Başının Kesilişi", "Herodes'i tövbeye çağıran öncü, Herodias'ın kızının isteğiyle hapsedildi ve başı kesildi. Ölümü hakikate tanıklık olarak anılır.", "Hakikati söyleyenler"),
    ("August 30", "Margaret Ward, Margaret Clitherow and Anne Line", "Margaret Ward, Margaret Clitherow ve Anne Line", "I. Elizabeth döneminde Katoliklere yönelik zulüm sırasında rahipleri barındırdıkları için şehit edilen üç İngiliz kadın.", "Cesur kadınlar, barınak verenler"),
    ("August 31", "John Bunyan", "John Bunyan", "Ruhsatsız vaaz verdiği için hapsedilen ve hapishanede 'Hacı'nın Yolculuğu'nu yazan İngiliz Baptist vaiz ve yazar (1628-1688). 31 Ağustos'ta öldü.", "Yazarlar, mahkûmlar, hacılar"),

    ("September 1", "Joshua the Prophet", "Peygamber Yeşu", "Musa'nın halefi; İsrail'i Ürdün'ün karşısına geçirdi ve 'ben ve evim Rab'be hizmet edeceğiz' diye ilan etti.", "Önderler, Rab'be hizmet eden aileler"),
    ("September 2", "N. F. S. Grundtvig", "N. F. S. Grundtvig", "Bin'den fazla ilahi yazan ve imanı ve öğrenmeyi sıradan insanların hizmetine sunan halk yüksekokulu hareketini kuran Danimarkalı papaz, şair ve eğitimci (1783-1872).", "İlahi yazarları, eğitimciler, Danimarka"),
    ("September 3", "Phoebe the Deacon", "Diyakoz Phoebe", "Pavlus'un Romalılar'a tavsiye ettiği 'Kenhreya kilisesinin hizmetkârı' ve mektubunu Roma'ya taşıdığı düşünülen kişi.", "Diyakozlar, hizmetteki kadınlar"),
    ("September 4", "Moses the Lawgiver", "Yasa Koyucu Musa", "İsrail'i Mısır'dan çıkaran ve Sina'da yasayı alan, Tanrı'yla 'bir adamın dostuyla konuşması gibi' yüz yüze konuşan peygamber.", "Önderler, özgürlük arayanlar"),
    ("September 5", "Katharina Zell", "Katharina Zell", "Bir rahiple evlenen, din adamlarının evliliğini yazıyla savunan, mültecilere bakan ve ilahiler yayımlayan Strasbourg reformcusu (yaklaşık 1497-1562).", "Kadın reformcular, mülteciler"),
    ("September 6", "Hannah More", "Hannah More", "Mendip Tepeleri'nde yoksullar için okullar kuran ve köle ticaretine karşı yazan İngiliz yazar ve hayırsever (1745-1833).", "Öğretmenler, yazarlar"),
    ("September 7", "Kassiani the Hymnographer", "İlahi Yazarı Kassiani", "Kutsal Çarşamba için yazdığı ve bugün de söylenen ilahisi Mesih'in ayaklarını meshetmiş kadının hikâyesini anlatan Bizans başrahibe ve besteci (yaklaşık 810-865).", "İlahi yazarları, kadın besteciler"),
    ("September 9", "Peter Claver", "Peter Claver", "Cartagena'ya gelen köleleştirilmiş Afrikalılara hizmet eden ve kendine 'kölelerin ebedi kölesi' diyen İspanyol Cizvit (1580-1654).", "Köleleştirilenlere hizmet edenler"),
    ("September 10", "Alexander Crummell", "Alexander Crummell", "Liberya'da bilgin ve misyoner olan, Amerikan Zenci Akademisi'ni kuran ve Siyah kilisenin onurunu savunan Afro-Amerikalı Episkopal rahip (1819-1898).", "Bilginler, Liberya"),
    ("September 12", "John Henry Hobart", "John Henry Hobart", "Amerikan Devrimi'nden sonra Kilise'nin canlanmasında önder olan New York Episkopal piskoposu (1775-1830).", "Piskoposlar"),
    ("September 13", "John Chrysostom", "Yuhanna Chrysostomos", "Vaazlarıyla 'altın ağızlı' adını kazanan İstanbul Başpiskoposu (yaklaşık 347-407). Yoksullara bakımı savundu ve saray tarafından sürgün edildi.", "Vaizler"),
    ("September 14", "Holy Cross Day", "Kutsal Haç Günü", "Kilise haçı kurtuluşun işareti olarak yükseltir ve Kudüs'te Gerçek Haç'ın bulunuşunu anar. 'Sana tapıyoruz Mesih, seni kutsuyoruz, çünkü kutsal haçınla dünyayı kurtardın'.", "Acı çekenler, inananlar"),
    ("September 15", "Catherine of Genoa", "Cenovalı Catherine", "Cenova'da bir hastanede çalışan ve araf ile Tanrı sevgisi üzerine yazan İtalyan mistik ve hemşire (1447-1510).", "Hemşireler, mistikler"),
    ("September 16", "Cyprian of Carthage", "Kartaca'lı Cyprianus", "Kilise'yi veba ve zulümden geçirerek bir arada tutan, 'Kilise'nin Birliği Üzerine' yazan ve şehit olarak ölen Kartaca Piskoposu (yaklaşık 200-258).", "Piskoposlar, kilise birliği"),
    ("September 17", "Hildegard of Bingen", "Bingen'li Hildegard", "'Scivias', kutsal müzik ve doğal tıp üzerine eserler yazan Alman başrahibe, besteci, yazar, şifacı ve vizyoner (1098-1179).", "Besteciler, yaratılışı sevenler"),
    ("September 18", "Dag Hammarskjold", "Dag Hammarskjöld", "Özel günlüğü 'Markings' derin bir Hıristiyan imanı gösteren Birleşmiş Milletler Genel Sekreteri İsveçli diplomat (1905-1961). Bir barış misyonunda uçak kazasında öldü.", "Barış yapıcılar, diplomatlar"),
    ("September 19", "Theodore of Tarsus", "Tarsus'lu Theodore", "66 yaşında Canterbury başpiskoposu atanan, İngiliz Kilisesi'ni örgütleyen ve okullar kuran Yunan keşiş (yaklaşık 602-690).", "Başpiskoposlar, öğretmenler"),
    ("September 20", "John Coleridge Patteson and Companions", "John Coleridge Patteson ve Arkadaşları", "Adalılar için bir okul kurduktan sonra Nukapu adasında başkalarıyla birlikte öldürülen Melanezya Anglikan piskoposu (1827-1871).", "Pasifik adalılar, şehitler"),
    ("September 21", "Matthew, Apostle and Evangelist", "Havari ve Müjdeci Matta", "İsa tarafından kulübesinden çağrılan ve Yeni Antlaşma'yı başlatan İncil'i yazan vergi görevlisi.", "Müjdeciler, hayatını değiştirenler"),
    ("September 22", "Jonah the Prophet", "Peygamber Yunus", "Tanrı'nın Ninova çağrısından kaçan, büyük bir balık tarafından yutulan ve sonra Rab'be dönen bir şehre tövbeyi vaaz eden peygamber.", "Tanrı'nın çağrısından kaçanlar"),
    ("September 23", "Thecla of Iconium", "Konya'lı Thecla", "Aziz Pavlus'un vaazıyla dönüşen ve 'Pavlus ve Thecla'nın Eylemleri'nde ilk kadın şehit (yaklaşık 70) olarak onurlandırılan erken Hıristiyan kadın.", "Kadın müritler"),
    ("September 24", "Anna Alexander", "Anna Alexander", "Georgia'da Siyah çocuklar için bir kilise ve okul kuran ve yöneten Afro-Amerikalı Episkopal kadın diyakoz ve öğretmen (1865-1947).", "Öğretmenler, kadın diyakozlar"),
    ("September 25", "The Peace of Augsburg", "Augsburg Barışı", "25 Eylül 1555'te sonuçlanan barış, Lutheran prenslere Kutsal Roma İmparatorluğu'nda imanlarını uygulama hakkı verdi ve on yıllarca süren çatışmayı bitirdi.", "Barış yapıcılar, Lutheran kiliseler"),
    ("September 26", "Lancelot Andrewes", "Lancelot Andrewes", "King James Kutsal Kitabı'nın çevirmenlerinden olan, 'Özel Dualar'ı yaygın sevilen Anglikan piskopos (1555-1626).", "Bilginler, dua edenler"),
    ("September 27", "Euphrosyne of Alexandria", "İskenderiyeli Euphrosyne", "Smaragdus adlı bir keşiş kılığına girip otuz sekiz yıl bir manastırda yaşayan beşinci yüzyıl genç kadını.", "Yalnızlık arayanlar"),
    ("September 28", "Paula and Eustochium", "Paula ve Eustochium", "Jerome'u Beytüllahim'e izleyen, manastırlar kuran ve Kutsal Kitap çevirisine yardım eden Romalı anne (347-404) ve kızı.", "Çevirmenler, rahibeler"),
    ("September 29", "Michael and All Angels", "Mikail ve Tüm Melekler", "Kilise başmelek Mikail'i ve Tanrı'ya hizmet edip halkını koruyan tüm melekleri onurlandırır. 'Ey Rab'bin melekleri, sözünü yerine getiren güçlüler, Rab'bi övün'.", "Melekler, koruyucular"),
    ("September 30", "Jerome", "Jerome", "Kutsal Kitap'ı Latince'ye (Vulgata) çeviren ve tefsirler yazan Latin bilgin (yaklaşık 347-420). Lutheranlar ve Anglikanlar onu Kutsal Yazılar'ın çevirmeni olarak onurlandırır.", "Çevirmenler, bilginler, kütüphaneciler"),

    ("October 1", "Remigius of Rheims", "Reims'li Remigius", "Frank kralı Clovis'i vaftiz eden ve böylece Frank halkının Kilise'ye girmesine yardım eden Reims Piskoposu (yaklaşık 437-533).", "Piskoposlar, Fransa"),
    ("October 3", "John R. Mott", "John R. Mott", "Dünya Öğrenci Hıristiyan Federasyonu'nu kurmaya yardım eden ve ekümenik harekete önderlik eden Amerikalı Metodist meslekten olmayan kişi (1865-1955). 1946'da Nobel Barış Ödülü aldı.", "Öğrenciler, ekümenistler"),
    ("October 4", "Francis of Assisi", "Assisi'li Francis", "Yoksulluğu benimseyen, kuşlara vaaz veren ve stigmata alan İtalyan keşiş (yaklaşık 1181-1226). Lutheran ve Anglikan takvimleri onu Kilise'nin yenileyicisi olarak onurlandırır.", "Hayvanlar, yoksullar, yaratılış"),
    ("October 7", "Henry Melchior Muhlenberg", "Henry Melchior Muhlenberg", "Pennsylvania'da ve sömürgelerde cemaatler örgütleyen, 'Amerika'daki Lutheran Kilisesi'nin patriği' olan Almanya doğumlu papaz (1711-1787).", "Papazlar, Amerika'daki Lutheranlar"),
    ("October 9", "Abraham the Patriarch", "Patrik İbrahim", "Tanrı'nın çağrısıyla yurdunu terk eden ve yıldızlar kadar çok torun vaadine güvenen, iman edenlerin babası.", "İmanla adım atanlar"),
    ("October 10", "Vida Dutton Scudder", "Vida Dutton Scudder", "Wellesley'de profesör olan ve Endüstriyel Demokrasi için Kilise Birliği'nin kurulmasına yardım eden Amerikalı Episkopal eğitimci ve sosyal reformcu (1861-1954).", "Öğretmenler, sosyal reformcular"),
    ("October 11", "Philip the Evangelist", "Müjdeci Filipus", "Kudüs kilisesinin yedi diyakozundan biri; Samiriye'de vaaz verdi ve Etiyopyalı görevliyi vaftiz etti; dört kızı peygamberlik etti.", "Müjdeciler, diyakozlar"),
    ("October 12", "Edith Cavell", "Edith Cavell", "Alman işgali altındaki Belçika'dan yüzlerce Müttefik askerinin kaçmasına yardım eden ve 12 Ekim'de idam edilen İngiliz hemşire (1865-1915). Son sözleri: 'Vatanseverlik yetmez'.", "Hemşireler, adaletsizliğe direnenler"),
    ("October 14", "Samuel Schereschewsky", "Samuel Schereschewsky", "Şanghay Episkopal piskoposu olan ve felce rağmen Kutsal Kitap'ı Çinceye çeviren Litvanya doğumlu Yahudi dönmesi (1831-1906).", "Çevirmenler, Çin"),
    ("October 15", "Teresa of Avila", "Ávila'lı Teresa", "'İç Şato'yu yazan ve duanın 'dostlar arasında yakın bir paylaşım' olduğunu öğreten İspanyol Karmelit reformcu ve mistik (1515-1582).", "Mistikler, dua edenler"),
    ("October 16", "Hugh Latimer, Nicholas Ridley and Thomas Cranmer", "Hugh Latimer, Nicholas Ridley ve Thomas Cranmer", "Kraliçe I. Mary altında Oxford'da yakılan üç Anglikan piskopos: Latimer ve Ridley 16 Ekim 1555'te, Cranmer 1556'da. Latimer 'bugün bir mum yakacağız' dedi.", "İngiliz Reformu şehitleri"),
    ("October 17", "Ignatius of Antioch", "Antakyalı Ignatius", "Yaklaşık 115'te Roma'da şehit edilen Antakya piskoposu. Yolda kiliselere birlik ve sevgiyi teşvik eden mektuplar yazdı.", "Piskoposlar, kilise birliği"),
    ("October 18", "Luke, Evangelist", "Müjdeci Luka", "Pavlus'un arkadaşı olan, yoksullara, kadınlara ve dışlanmışlara özel ilgisiyle Luka İncili ve Elçilerin İşleri'ni yazan hekim.", "Hekimler, sanatçılar"),
    ("October 19", "Henry Martyn", "Henry Martyn", "Yeni Antlaşma'yı Urduca ve Farsça'ya çeviren ve 31 yaşında Türkiye'nin Tokat kentinde ölen Anglikan rahip ve misyoner (1781-1812).", "Çevirmenler, misyonerler"),
    ("October 20", "Cornelius the Centurion", "Yüzbaşı Kornelius", "Hanesi Petrus tarafından vaftiz edilen ilk Yahudi olmayan aile olan Sezarya'lı Romalı subay; İncil'in tüm halklar için olduğunun işareti.", "Askerler, Yahudi olmayan inananlar"),
    ("October 23", "James of Jerusalem", "Kudüslü Yakup", "'Doğru' denen, Kudüs konsiline başkanlık eden ve Yakup mektubunu yazan Rab'bin kardeşi ve Kudüs'ün ilk piskoposu.", "Piskoposlar, kilise birliği"),
    ("October 25", "Tabitha (Dorcas) of Joppa", "Yafa'lı Tabita (Dorkas)", "'İyi işler ve hayırlarla dolu' olan ve Petrus'un Yafa'da ölümden kaldırdığı öğrenci. Dullar ona yaptığı giysileri gösterdi.", "Terziler, yoksullara hizmet edenler"),
    ("October 26", "Philipp Nicolai, Johann Heermann and Paul Gerhardt", "Philipp Nicolai, Johann Heermann ve Paul Gerhardt", "On yedinci yüzyılın üç Alman Lutheran ilahi yazarı: Nicolai ('Wake, Awake'), Heermann ('Ah, Holy Jesus') ve Gerhardt ('O Sacred Head, Now Wounded').", "İlahi yazarları, korolar"),
    ("October 28", "Simon and Jude, Apostles", "Havariler Simon ve Yahuda", "On iki havariden ikisi, Gayretli Simon ve Yahuda Taddeus. Gelenek, birlikte İran'da vaaz verdiklerini ve şehit edildiklerini söyler.", "Havariler"),
    ("October 29", "James Hannington and Companions", "James Hannington ve Arkadaşları", "Kral Mwanga'nın emriyle arkadaşlarıyla birlikte Uganda'da öldürülen Doğu Ekvator Afrikası Anglikan piskoposu (1847-1885).", "Uganda, şehitler"),
    ("October 30", "Maryam of Qidun", "Qidun'lu Meryem", "Dördüncü yüzyılda kendini duaya adayan ve amcası Qidun'lu Abraham'a bakan Suriyeli genç kadın.", "Aileye bakanlar"),
    ("October 31", "Reformation Day", "Reform Günü", "31 Ekim 1517'de Martin Luther, Doksan Beş Tezi'ni Wittenberg'deki Şato Kilisesi'nin kapısına astı ve Protestan Reformu'nu başlattı. 'Doğru kişi iman ile yaşayacak'.", "Reform, tüm Protestan kiliseler"),

    ("November 2", "All Souls", "Ölüler Günü", "Episkopal Kilisesi, tüm ölmüş inananları anar ve onları Tanrı'nın merhametine emanet eder. 'Ey Rab, onlara sonsuz huzur ver ve sürekli ışık üzerlerine parlasın'.", "Ölenler, yas tutanlar"),
    ("November 3", "Richard Hooker", "Richard Hooker", "'Kilise Yönetiminin Yasaları'yla İngiltere Kilisesi'ni savunan ve Kutsal Yazılar, gelenek ve akıl dengesini öğreten Anglikan rahip ve ilahiyatçı (1554-1600).", "İlahiyatçılar, öğretmenler"),
    ("November 4", "Adeline Blanchard Tyler and Companions", "Adeline Blanchard Tyler ve Arkadaşları", "Episkopal Kilisesi tarafından Afrika ve Filipinler'deki çalışmalarıyla anılan misyonerler.", "Misyonerler"),
    ("November 6", "William Temple", "William Temple", "İngiliz refah devletinin ve Dünya Kiliseler Konseyi'nin temellerini atan ilahiyatçı ve sosyal reformcu Canterbury Başpiskoposu (1881-1944).", "Başpiskoposlar, sosyal reformcular"),
    ("November 7", "Willibrord, Missionaries to the Netherlands", "Willibrord, Hollanda'ya Misyonerler", "'Frizyalıların havarisi' olan Northumbria'lı piskopos (658-739). Lutheran takvimi Heyer, Ziegenbalg ve Nommensen'i de, Hindistan ve Endonezya misyonerlerini de anar.", "Misyonerler"),
    ("November 8", "Johann von Staupitz", "Johann von Staupitz", "Luther'in üstü ve günah çıkarıcısı (yaklaşık 1460-1524); ona gerçek tövbenin Tanrı sevgisiyle başladığını öğretti ve onu Kutsal Yazılar'a yöneltmeye yardım etti.", "Günah çıkarıcılar, akıl hocaları"),
    ("November 9", "Martin Chemnitz and the Mystics of England", "Martin Chemnitz ve İngiltere'nin Mistikleri", "Martin Chemnitz (1522-1586), Uyum Formülü'nü yazmaya yardım eden bir Lutheran ilahiyatçıydı. Episkopal Kilisesi İngiliz mistikleri Richard Rolle, Walter Hilton ve Margery Kempe'i anar.", "İlahiyatçılar, mistikler"),
    ("November 10", "Martin Luther's Birthday", "Martin Luther'in Doğum Günü", "Martin Luther 10 Kasım 1483'te Eisleben'de doğdu; 1546'da aynı kasabada öldü. Kilise, doğumunu ve Kutsal Yazılar ve lütuf öğretmeni olarak çalışmasını anar.", "Reformcular, Kutsal Yazılar'ın öğretmenleri"),
    ("November 11", "Martin of Tours", "Tours'lu Martin", "Pelerinini bir dilenciyle paylaştığı ünlü Romalı asker, sonra piskopos (yaklaşık 316-397). Lutheranlar onu onurlandırır; Luther'in kendisi de onun bayramında vaftiz edildi.", "Askerler, yoksullar"),
    ("November 12", "Charles Simeon", "Charles Simeon", "54 yıl Cambridge'deki Holy Trinity'de hizmet eden, birçok genç din adamı yetiştiren ve misyon derneklerini destekleyen Anglikan rahip (1759-1836).", "Vaizler, misyonerler"),
    ("November 14", "Justinian and the Consecration of Samuel Seabury", "Justinianus ve Samuel Seabury'nin Kutsanışı", "Lutheran takvimi Ayasofya'yı yaptıran ve Roma hukukunu derleyen İmparator Justinianus'u (ö. 565) anar. Episkopal Kilisesi 1784'te Samuel Seabury'nin ilk Amerikan piskoposu olarak kutsanışını anar.", "Piskoposlar, inşaatçılar"),
    ("November 15", "Herman of Alaska", "Alaska'lı Herman", "Spruce Adası'nda Aleut halkına hizmet eden ve onları istismardan koruyan Rus Ortodoks keşiş (yaklaşık 1756-1837).", "Alaska yerlileri, keşişler"),
    ("November 16", "Margaret of Scotland", "İskoçyalı Margaret", "Kilise reformunu destekleyen, yetimlere ve yoksullara bakan Anglo-Sakson prenses ve İskoçya Kraliçesi (yaklaşık 1045-1093).", "Kraliçeler, anneler"),
    ("November 17", "Elisabeth of Hungary", "Macaristanlı Elisabeth", "Yoksullara ve hastalara bakan, hastaneler yaptıran ve mallarını veren Macar prenses (1207-1231). ELCA onu 17 Kasım'da anar.", "Yoksullar, hemşireler"),
    ("November 18", "Hilda of Whitby", "Whitby'li Hilda", "Whitby Sinodu'na ev sahipliği yapan ve ilk İngiliz Hıristiyan şairi Caedmon'u teşvik eden İngiliz başrahibe (614-680).", "Başrahibeler, şairler"),
    ("November 19", "Elizabeth of Hungary", "Macaristanlı Elizabeth", "Yoksullara ekmek veren ve cüzzamlılara bakan prenses ve hayırsever. Bayramı farklı takvimlerde 17 ya da 19 Kasım'dadır.", "Yoksullar, dullar"),
    ("November 20", "Edmund, King and Martyr", "Kral ve Şehit Edmund", "Mesih'i inkâr etmeyi reddettiği için Danimarkalı akıncılar tarafından öldürülen Doğu Anglia kralı (yaklaşık 841-870).", "Krallar, Doğu Anglia"),
    ("November 21", "Gertrude the Great and Mechthilde of Hackeborn", "Büyük Gertrude ve Hackeborn'lu Mechthilde", "Helfta manastırının, Mesih'in sevgisini yazan ve Kutsal Yazılar'a ve litürjiye büyük önem veren Alman rahibeleri ve mistikleri.", "Mistikler, rahibeler"),
    ("November 22", "C. S. Lewis", "C. S. Lewis", "'Mere Christianity', 'The Screwtape Letters' ve 'Narnia Günlükleri'nin yazarı Oxford ve Cambridge bilgini ve savunmacı (1898-1963). 22 Kasım'da öldü.", "Yazarlar, savunmacılar, okurlar"),
    ("November 23", "Clement of Rome", "Romalı Clement", "Korint'e barış ve düzen çağrısı yapan bir mektup yazan, yaklaşık 92-101'de Roma piskoposu. Lutheranlar ve Episkopaller onu 23 Kasım'da anar.", "Kilise birliği, piskoposlar"),
    ("November 24", "John Knox, Justus Falckner and Jehu Jones", "John Knox, Justus Falckner ve Jehu Jones", "John Knox (yaklaşık 1514-1572) İskoç Reformu'na önderlik etti ve 24 Kasım'da öldü. Lutheranlar Amerikalı papazlar Justus Falckner, Jehu Jones ve William Passavant'ı da anar.", "Reformcular, papazlar"),
    ("November 25", "Isaac Watts", "Isaac Watts", "'Joy to the World' ve 'When I Survey the Wondrous Cross' yazarı, 'İngiliz ilahi yazımının babası' İngiliz Kongregasyonalist papaz (1674-1748).", "İlahi yazarları, korolar"),
    ("November 26", "Sojourner Truth", "Sojourner Truth", "Özgür kalmış köle ve vaiz Sojourner Truth (yaklaşık 1797-1883) kadınların eşitliği ve kölelik karşıtlığı için konuştu. 26 Kasım'da öldü.", "Kölelik karşıtları, kadınlar"),
    ("November 28", "Kamehameha IV and Queen Emma of Hawaii", "IV. Kamehameha ve Hawaii Kraliçesi Emma", "Hawaii'de Anglikan Kilisesi'ni ve Kraliçe Hastanesi'ni kuran Hawaii kralı ve kraliçesi (1834-1863; 1836-1885).", "Hawaii, hastane kurucuları"),
    ("November 29", "Noah the Patriarch", "Patrik Nuh", "Tanrı'nın emriyle gemiyi yapan ve ailesiyle tufandan kurtulan doğru adam. Tanrı gökkuşağını antlaşmasının işareti yaptı.", "Alay edilse de Tanrı'ya itaat edenler"),
    ("November 30", "Andrew, Apostle", "Havari Andreas", "İsa'yı ilk izleyen ve kardeşi Petrus'u O'na getiren balıkçı. Andreas İskoçya, Yunanistan ve Rusya'nın koruyucusu olarak onurlandırılır.", "Balıkçılar, misyonerler"),

    ("December 1", "Charles de Foucauld", "Charles de Foucauld", "Sahra'da Tuaregler arasında sessiz varlığın tanığı olarak yaşayan Fransız münzevi (1858-1916). 1 Aralık'ta öldürüldü.", "Münzeviler, yabancılar arasında yaşayanlar"),
    ("December 2", "Martyrs of El Salvador", "El Salvador Şehitleri", "2 Aralık 1980'de El Salvador'da askerler tarafından öldürülen dört Amerikalı kadın misyoner: Maura Clarke, Ita Ford, Dorothy Kazel ve Jean Donovan.", "Misyonerler, yoksullar"),
    ("December 3", "Francis Xavier", "Francis Xavier", "İncil'i Hindistan, Güneydoğu Asya ve Japonya'ya taşıyan İspanyol Cizvit misyoner (1506-1552). 3 Aralık'ta Çin kıyısındaki Sancian Adası'nda öldü.", "Misyonerler, Asya"),
    ("December 4", "John of Damascus", "Şamlı Yuhanna", "İkonları savunan ve Paskalya'da hâlâ söylenen 'Diriliş Günü' dahil ilahiler yazan Süryani keşiş ve ilahiyatçı (yaklaşık 675-749).", "İlahi yazarları, ilahiyatçılar"),
    ("December 5", "Clement of Alexandria", "İskenderiyeli Clement", "İskenderiye ilmihal okulunun başında olan ve felsefenin Mesih'e hazırladığını savunan Yunan Hıristiyan öğretmen (yaklaşık 150-215).", "Öğretmenler, filozoflar"),
    ("December 6", "Nicholas of Myra", "Myra'lı Nikolaos", "Yoksullara gizli armağanlarıyla bilinen Küçük Asya'daki Myra piskoposu (ö. yaklaşık 342). Noel Baba figürü onun efsanesinden doğdu.", "Çocuklar, denizciler, gizlice verenler"),
    ("December 7", "Ambrose of Milan", "Milano'lu Ambrosius", "Augustinus'u vaftiz eden, ilahiler yazan ve Kilise'nin özgürlüğünü savunmak için imparatora karşı duran Milano Piskoposu (yaklaşık 339-397).", "Piskoposlar, ilahi yazarları"),
    ("December 8", "Nicholas Ferrar", "Nicholas Ferrar", "Little Gidding'de dua ve hayırseverliğe adanmış bir hane topluluğu kuran İngiliz Anglikan diyakoz (1593-1637).", "Diyakozlar, toplulukta yaşayanlar"),
    ("December 11", "Frederick Howden Jr.", "Frederick Howden Jr.", "II. Dünya Savaşı'nda askerlere hizmet eden ve Kuzey Afrika çıkarması sırasında öldürülen Episkopal rahip ve papaz (1900-1942).", "Askeri papazlar"),
    ("December 12", "Francis de Sales and Jane de Chantal", "Francis de Sales ve Jane de Chantal", "Ziyaret Rahibeleri'ni kuran Savoie'li piskopos (1567-1622) ve dul baron hanımı (1572-1641). Francis, meslekten olmayan kişiler için bir klasik olan 'Dindar Yaşama Giriş'i yazdı.", "Yazarlar, ruh yönetmenleri"),
    ("December 13", "Lucy of Syracuse", "Syrakusa'lı Lucy", "Adı 'ışık' anlamına gelen Sicilyalı bakire ve şehit (ö. 304). İsveç ve Norveç'te mum geçit törenleriyle Lucy Günü kışın karanlık günlerini aydınlatır.", "Işık, körler"),
    ("December 14", "John of the Cross", "Haçlı Yuhanna", "Karmelitlerin eş reformcusu olan, 'Ruhun Karanlık Gecesi' ve 'Ruhani Ezgi'yi yazan İspanyol Karmelit mistik (1542-1591).", "Mistikler, şairler"),
    ("December 15", "Nino of Georgia", "Gürcistan'lı Nino", "Kraliçeyi iyileştirdikten sonra İncil'i Gürcistan'a getiren dördüncü yüzyıl köle kadını (yaklaşık 296-332). 'Gürcistan'ın aydınlatıcısı' olarak onurlandırılır.", "Gürcistan, kadın müjdeciler"),
    ("December 17", "Daniel and the Three Young Men", "Daniel ve Üç Genç", "Babil'de sadık kalan ve aslan çukurunda ve ateş fırınında Tanrı'ya güvenen Daniel ve arkadaşları Şadrak, Meşak ve Abed-Nego.", "Sürgünde sadık kalanlar"),
    ("December 18", "Charles Wesley's Birthday", "Charles Wesley'nin Doğum Günü", "Charles Wesley 18 Aralık 1707'de doğdu ve 'Hark! The Herald Angels Sing', 'Love Divine' ve 'And Can It Be' dahil yaklaşık altı bin ilahi yazdı.", "İlahi yazarları, korolar"),
    ("December 19", "Adam and Eve", "Adem ve Havva", "Tanrı'nın suretinde yaratılan, düşüşleri ve kurtuluş vaatleri Kutsal Kitap'ın kurtuluş hikâyesini çerçeveleyen ilk adam ve kadın.", "Aileler, ilk ebeveynler"),
    ("December 20", "Katharina von Bora Luther", "Katharina von Bora Luther", "Martin Luther'le evlenen, Kara Manastır'ın evini ve çiftliğini yöneten ve Reform evliliği ve konukseverliğinin örneği olan eski rahibe (1499-1552).", "Eşler, anneler, ev yöneticileri"),
    ("December 21", "Thomas, Apostle", "Havari Tomas", "Mesih'in yaralarına dokunan ve 'Rabbim ve Tanrım' diyen havari. Bayramı Lutheran ve Episkopal takvimlerinde 21 Aralık'tadır.", "Şüphe edenler, Hindistan"),
    ("December 22", "D. L. Moody's Death", "D. L. Moody'nin Ölümü", "Ayakkabı satıcısından müjdeciye dönüşen Dwight L. Moody (1837-1899), Amerika ve Britanya'da milyonlara vaaz verdi, okullar ve Moody Kutsal Kitap Enstitüsü'nü kurdu. 22 Aralık'ta öldü.", "Müjdeciler, Kutsal Kitap okulları"),
    ("December 24", "Vigil of the Nativity", "Noel Arifesi Nöbeti", "Noel Arifesi'nde Kilise nöbet tutar, peygamberlikleri ve İsa'nın doğum İncil'ini okur ve Mesih'in ışığını karşılamaya hazırlanır.", "Kurtarıcı'yı bekleyenler"),
    ("December 26", "Stephen, Deacon and Martyr", "Diyakoz ve Şehit Stephanos", "Yoksullara hizmet eden ve 'Rab, bu günahı onlara yükleme' diye dua ederken Kudüs'te taşlanan ilk Hıristiyan şehit, bir diyakoz.", "Diyakozlar, şehitler"),
    ("December 27", "John, Apostle and Evangelist", "Havari ve Müjdeci Yuhanna", "Son Akşam Yemeği'nde Rab'bin göğsüne yaslanan sevgili öğrenci. Gelenek, dördüncü İncil'i, üç mektubu ve Vahiy Kitabı'nı yazdığını söyler.", "Yazarlar, ilahiyatçılar"),
    ("December 29", "David the King", "Kral Davut", "İsrail kralı olan çoban çocuk, 'tatlı mezmur yazarı' ve İsa'nın atası. Lutheran takvimi onu Noel'i izleyen günlerde anar.", "Krallar, müzisyenler, mezmur yazarları"),
    ("December 31", "John Wycliffe", "John Wycliffe", "Kutsal Kitap'ın ilk tam İngilizce çevirisini yönlendiren, 'Reform'un Sabah Yıldızı' denen İngiliz rahip ve bilgin (yaklaşık 1328-1384). 31 Aralık'ta öldü.", "Çevirmenler, reformcular"),
    ("December 9", "John Milton", "John Milton", "Düşüş ve kurtuluşun büyük destanı 'Kayıp Cennet'i ve 'Geri Kazanılmış Cennet'i yazan İngiliz şair (9 Aralık 1608'de doğdu). Gözlerini kaybettikten sonra da yazmayı sürdürdü.", "Şairler, yazarlar, körlüğe rağmen sebat edenler"),
    ("November 21", "Henry Purcell", "Henry Purcell", "Westminster Abbey orgcusu olan, Anglikan kilisesi ve sarayı için marşlar, odlar ve tiyatro müzikleri yazan İngiliz besteci (yaklaşık 1659-1695). 21 Kasım 1695'te öldü.", "Kilise müzisyenleri, orgcular, besteciler"),
]
